LEDGER = 'explorations/fortress-gap-ledger.md'
SEP = re.compile(r'(?<!\\)\|')

def load():
    return open(LEDGER, encoding='utf-8').read().split('\n')

def save(L):
    open(LEDGER, 'w', encoding='utf-8').write('\n'.join(L))

def idx(L, n):
    hits = [i for i, l in enumerate(L) if l.startswith('| %d | ' % n)]
    assert len(hits) == 1, (n, hits)
    return hits[0]

def cells(line):
    parts = SEP.split(line)
    assert parts[0] == '' and parts[-1].strip() == '', line[:80]
    return [p.strip() for p in parts[1:-1]]

def join(cs):
    return '| ' + ' | '.join(cs) + ' |'

def esc(text):
    return SEP.sub(r'\\|', text)

def append_note(L, n, text):
    # insert before the row's closing pipe, leaving the rest of the line byte for byte
    i = idx(L, n)
    line = L[i].rstrip()
    assert line.endswith('|') and not line.endswith('\\|')
    L[i] = line[:-1].rstrip() + ' ' + esc(text) + ' |'

def set_status(L, n, status):
    # the status is the third cell; replace it in place by the positions of the separators
    i = idx(L, n)
    line = L[i]
    pos = [m.start() for m in SEP.finditer(line)]
    assert len(pos) >= 9
    a, b = pos[2], pos[3]
    L[i] = line[:a + 1] + ' ' + status + ' ' + line[b:]

def get(L, n):
    return cells(L[idx(L, n)])

def insert_after(L, n_after, row_cells):
    assert len(row_cells) == 8
    i = idx(L, n_after)
    L.insert(i + 1, join([row_cells[0]] + [esc(c) for c in row_cells[1:]]))

